import java.io.*;
import java.util.*;

public class Main {
    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0, length = 0;

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    private static long[] generate(long[] values, long mod) {
        int size = 1 << values.length;
        long[] sums = new long[size];

        for (int mask = 1; mask < size; mask++) {
            int bit = Integer.numberOfTrailingZeros(mask);
            int previous = mask & (mask - 1);
            sums[mask] = (sums[previous] + values[bit]) % mod;
        }
        return sums;
    }

    private static int upperBound(long[] array, long target) {
        int left = 0, right = array.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (array[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        long m = fs.nextLong();

        long[] leftValues = new long[n / 2];
        long[] rightValues = new long[n - n / 2];

        for (int i = 0; i < n; i++) {
            long value = fs.nextLong() % m;
            if (i < leftValues.length) {
                leftValues[i] = value;
            } else {
                rightValues[i - leftValues.length] = value;
            }
        }

        long[] leftSums = generate(leftValues, m);
        long[] rightSums = generate(rightValues, m);
        Arrays.sort(rightSums);

        long answer = 0;

        for (long left : leftSums) {
            long limit = m - 1 - left;
            int index = upperBound(rightSums, limit) - 1;
            if (index >= 0) {
                answer = Math.max(answer, left + rightSums[index]);
            }
        }

        System.out.println(answer);
    }
}

