import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }
    }

    static long[] generate(long[] values, int from, int length, long mod) {
        int size = 1 << length;
        long[] sums = new long[size];
        int count = 1;

        for (int i = 0; i < length; i++) {
            long value = values[from + i] % mod;
            for (int j = 0; j < count; j++) {
                sums[count + j] = (sums[j] + value) % mod;
            }
            count <<= 1;
        }
        return sums;
    }

    static int upperBound(long[] array, long target) {
        int low = 0, high = array.length;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (array[mid] <= target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = (int) fs.nextLong();
        long m = fs.nextLong();

        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextLong();
        }

        if (m == 1) {
            System.out.println(0);
            return;
        }

        int leftLength = n / 2;
        int rightLength = n - leftLength;

        long[] left = generate(a, 0, leftLength, m);
        long[] right = generate(a, leftLength, rightLength, m);
        Arrays.sort(right);

        long answer = 0;
        long largestRight = right[right.length - 1];

        for (long x : left) {
            int index = upperBound(right, m - 1 - x) - 1;
            if (index >= 0) {
                answer = Math.max(answer, x + right[index]);
            }

            answer = Math.max(answer, (x + largestRight) % m);

            if (answer == m - 1) {
                break;
            }
        }

        System.out.println(answer);
    }
}
